insert into tt_private.plans(key,body) values ('three-day-foundation@1','{"schemaVersion":1,"id":"three-day-foundation","version":1,"name":"The 3-Day Foundation","description":"A steady rhythm. A stronger you. Eight weeks of training together.","schedule":"Mon / Wed / Fri \u00b7 7:00\u20137:50 AM","weeks":8,"notes":["The first three exercises are the priority.","Alternate sets with your partner. Rest 60\u201390 seconds between your own sets, up to 2 minutes for demanding lifts.","Leave 2\u20133 reps in reserve. Increase weights gradually when you reach the top of your rep range with good form.","Start unfamiliar exercises with lighter weights, and have a YMCA trainer check your setup."],"days":[{"id":"monday","weekday":1,"name":"Monday","focus":"Legs, Chest & Shoulders","exercises":[{"id":"leg-press","name":"Leg Press Machine","sets":3,"reps":"8\u201312","demo":{"instructor":"Jeff Nippard","url":"https://www.youtube.com/watch?v=nDh_BlnLCGc","verifiedOn":"2026-10-22","verification":"YouTube title and instructor metadata checked against the requested exercise. Playback is subject to YouTube availability."},"substitutions":[]},{"id":"chest-press","name":"Dumbbell Chest Press","sets":3,"reps":"8\u201312","demo":{"instructor":"Scott Herman","url":"https://www.youtube.com/watch?v=VmB1G1K7v94","verifiedOn":"2026-10-22","verification":"YouTube title and instructor metadata checked against the requested exercise. Playback is subject to YouTube availability."},"substitutions":[]},{"id":"landmine-press","name":"Landmine Shoulder Press","sets":2,"reps":"10/arm","demo":{"instructor":"Eric Cressey","url":"https://www.youtube.com/watch?v=jCfcGei-NqM","verifiedOn":"2026-10-22","verification":"YouTube title and instructor metadata checked against the requested exercise. Playback is subject to YouTube availability."},"substitutions":[]},{"id":"leg-extension","name":"Leg Extension Machine","sets":2,"reps":"10\u201315","demo":{"instructor":"Albert Dorner","url":"https://www.youtube.com